// Ports of persistence_test.go plus a compatibility test against a durable
// workspace written by the Go helper (tests/AtlasRuntime/Fixtures/go-workspace,
// generated by Fixtures/generate_oracle_test.go.txt).
import Foundation
import Testing
@testable import OmniFlowApp

struct AtlasPersistenceTests {
    @Test func durableAnalysisRestoresCommittedCursorAndEvidence() async throws {
        let attempt = Box(0)
        let session = try memoryFixture { request in
            attempt.value += 1
            if attempt.value == 2 { var frame = AtlasRuntimeFrame(type: "reply"); frame.analysisError = "interrupted"; return frame }
            if request.phase == "merge" {
                return reply(.init(text: (request.records ?? []).map(\.text).joined(separator: " "), consumedRecords: request.records?.count ?? 0))
            }
            let text = AtlasUTF8.prefix(request.text ?? "", 4000)
            let quote = AtlasUTF8.prefix(text, 80)
            return reply(.init(text: quote, quotes: [quote], consumedBytes: text.utf8.count))
        }
        let store = session.store!
        defer { AtlasFiles.removeTree(store.directory) }
        store.question = "Read the complete archive"
        try store.enablePersistence(resume: false)
        let source = "First: staging only.\n" + String(repeating: "café 紅熊猫\n", count: 2000) + "Final: production NOT approved."
        let entry = try store.put("fixture", Array(source.utf8), isText: true)
        await #expect(throws: AtlasRuntimeError.self) { try await session.memory.analyze(entry.id, goal: "") }
        let cursor = session.memory.jobs[entry.id]!.processedBytes
        #expect((3996...4000).contains(cursor) && session.memory.records.count == 1)
        store.close()
        let journal = store.path("task-memory.jsonl")
        let handle = FileHandle(forWritingAtPath: journal)!
        handle.seekToEndOfFile()
        handle.write(Data(#"{"record":"#.utf8)) // simulate process death during the next append
        try handle.close()
        let reopened = try AtlasPayloadStore(directory: store.directory)
        defer { reopened.close() }
        reopened.question = store.question
        try reopened.enablePersistence(resume: true)
        session.store = reopened
        let restored = AtlasTaskJournal(session: session)
        session.memory = restored
        try restored.restore()
        #expect(restored.jobs[entry.id]!.processedBytes == cursor && restored.records.count == 1 && restored.active == entry.id)
        while !restored.jobs[entry.id]!.complete { _ = try await restored.analyze(entry.id, goal: "") }
        #expect(restored.jobs[entry.id]!.processedBytes == entry.bytes)
        let data = try String(contentsOfFile: journal, encoding: .utf8)
        for line in data.trimmingCharacters(in: .whitespacesAndNewlines).split(separator: "\n") {
            #expect(AtlasJSON.isValid(Array(line.utf8)), "partial append was not recovered")
        }
        #expect(FileManager.default.fileExists(atPath: store.path(entry.id + ".gz")))
    }

    @Test func failedResumeNeverDeletesOrOverwritesWorkspace() throws {
        let store = try AtlasPayloadStore(directory: nil)
        defer { AtlasFiles.removeTree(store.directory) }
        store.question = "Original goal"
        try store.enablePersistence(resume: false)
        let entry = try store.put("fixture", Array("Important original evidence".utf8), isText: true)
        var other = try AtlasPayloadStore(directory: store.directory)
        other.question = store.question
        #expect(throws: AtlasRuntimeError("checkpoint_in_use")) { try other.enablePersistence(resume: true) }
        other.close()
        _ = try store.data(entry.id)
        store.close()
        other = try AtlasPayloadStore(directory: store.directory)
        other.question = "Different goal"
        #expect(throws: AtlasRuntimeError.self) { try other.enablePersistence(resume: true) }
        other.close()
        #expect(FileManager.default.fileExists(atPath: store.path(entry.id + ".gz")))
        other = try AtlasPayloadStore(directory: store.directory)
        other.question = store.question
        #expect(throws: AtlasRuntimeError("checkpoint_already_exists")) { try other.enablePersistence(resume: false) }
        other.close()
    }

    @Test(arguments: [false, true]) func restoreRejectsDamagedOrRedirectedEvidence(redirected: Bool) throws {
        let store = try AtlasPayloadStore(directory: nil)
        defer { AtlasFiles.removeTree(store.directory) }
        store.question = "Evidence"
        try store.enablePersistence(resume: false)
        let entry = try store.put("fixture", Array("Original evidence".utf8), isText: true)
        store.close()
        let path = store.path(entry.id + ".gz")
        if redirected {
            try FileManager.default.moveItem(atPath: path, toPath: path + ".original")
            try FileManager.default.createSymbolicLink(atPath: path, withDestinationPath: path + ".original")
        } else {
            try Data("damaged gzip".utf8).write(to: URL(fileURLWithPath: path))
        }
        let other = try AtlasPayloadStore(directory: store.directory)
        other.question = store.question
        #expect(throws: AtlasRuntimeError("invalid_checkpoint")) { try other.enablePersistence(resume: true) }
        other.close()
    }

    /// Copies the Go-written workspace into a private directory (git does not
    /// keep 0600/0700 modes).
    static func goWorkspace() throws -> (ScratchDirectory, String, [String: AtlasJSON]) {
        let scratch = ScratchDirectory()
        let target = scratch.file("workspace")
        try FileManager.default.copyItem(atPath: Fixtures.directory.appendingPathComponent("go-workspace").path, toPath: target)
        try FileManager.default.setAttributes([.posixPermissions: 0o700], ofItemAtPath: target)
        for name in try FileManager.default.contentsOfDirectory(atPath: target) {
            try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: (target as NSString).appendingPathComponent(name))
        }
        let summary = try AtlasJSON.parse(Array(Data(contentsOf: Fixtures.directory.appendingPathComponent("go-workspace-summary.json")))).dictionary!
        return (scratch, target, summary)
    }

    @Test func resumesWorkspaceWrittenByGoHelper() async throws {
        let (scratch, workspace, summary) = try Self.goWorkspace()
        _ = scratch
        let session = try memoryFixture(store: workspace) { request in
            if request.phase == "merge" {
                return reply(.init(text: (request.records ?? []).map(\.text).joined(separator: " "), consumedRecords: request.records?.count ?? 0))
            }
            let text = AtlasUTF8.prefix(request.text ?? "", 3000)
            let quote = AtlasUTF8.prefix(text, 60)
            return reply(.init(text: "Note: " + quote, quotes: [quote], consumedBytes: text.utf8.count))
        }
        let store = session.store!
        store.question = summary["question"]!.stringValue!
        try store.enablePersistence(resume: true)
        defer { store.close() }
        let id = summary["payloadID"]!.stringValue!
        #expect(store.order == ["p1", "p2", "p3"])
        #expect(store.entries["p2"]?.kind == "schema" && store.entries["p3"]?.kind == "binary" && store.entries["p1"]?.sha256 == summary["sourceSHA256"]?.stringValue)
        let journal = session.memory!
        try journal.restore()
        let job = journal.jobs[id]!
        #expect(job.processedBytes == Int(summary["cursor"]!.doubleValue!) && job.totalBytes == Int(summary["total"]!.doubleValue!))
        #expect(journal.records.count == Int(summary["records"]!.doubleValue!))
        #expect(journal.receipts == summary["receipts"]!.arrayValue!.compactMap(\.stringValue))
        #expect(journal.active == id)
        // The torn final append was discarded before any new checkpoint.
        let lines = try String(contentsOfFile: store.path("task-memory.jsonl"), encoding: .utf8).split(separator: "\n")
        #expect(lines.allSatisfy { AtlasJSON.isValid(Array($0.utf8)) })
        // Exact quote provenance from Go-written notes resolves against Go-written evidence.
        let (source, _) = try store.data(id)
        for record in journal.records {
            for reference in record.sources ?? [] {
                #expect(String(decoding: source[reference.startByte..<reference.endByte], as: UTF8.self) == reference.quote)
            }
        }
        while !journal.jobs[id]!.complete { _ = try await journal.analyze(id, goal: "") }
        #expect(journal.jobs[id]!.processedBytes == job.totalBytes)
        #expect(journal.record(journal.jobs[id]!.result ?? "") != nil)
        // The Swift-extended workspace restores again from disk.
        store.close()
        let again = try AtlasPayloadStore(directory: workspace)
        again.question = store.question
        try again.enablePersistence(resume: true)
        defer { again.close() }
        session.store = again
        let reloaded = AtlasTaskJournal(session: session)
        try reloaded.restore()
        #expect(reloaded.jobs[id]!.complete && reloaded.records.count == journal.records.count)
    }

    @Test func swiftJournalMatchesGoEventShapes() throws {
        let session = try memoryFixture { _ in reply(.init()) }
        defer { session.store.close() }
        let entry = try session.store.put("fixture", Array("Final: production NOT approved.".utf8), isText: true)
        _ = try session.memory.commit(nil, AtlasRuntimeAnalysisJob(id: entry.id, goal: "g", processedBytes: 0, totalBytes: entry.bytes,
                                                                  level: [], next: [], reduced: 0, complete: false, result: nil))
        try session.memory.receipt("mcp", ["operation": .string("call"), "server": .string("s1"), "name": .string("read_archive")], success: true)
        let lines = try String(contentsOfFile: session.store.path("task-memory.jsonl"), encoding: .utf8).split(separator: "\n").map(String.init)
        #expect(lines == [
            #"{"job":{"id":"p1","goal":"g","processedBytes":0,"totalBytes":31,"level":[],"next":[],"reduced":0,"complete":false}}"#,
            #"{"operationReceipt":"mcp call s1 read_archive completed"}"#
        ])
    }

    /// Regression for a lock flake. While any process spawns a child, the
    /// child briefly shares every open file description (close-on-exec ones
    /// included) until its exec completes, so a lock released by one run can
    /// look held to the next. Relocking must ride that out; a live run must
    /// still be reported as in use.
    @Test func lockReleaseSurvivesConcurrentProcessSpawns() throws {
        let scratch = ScratchDirectory()
        let stop = Box(false)
        let spawner = Thread {
            while !stop.value {
                var pid: pid_t = 0
                var argv: [UnsafeMutablePointer<CChar>?] = [strdup("/usr/bin/true"), nil]
                if posix_spawn(&pid, "/usr/bin/true", nil, nil, &argv, nil) == 0 { var status: Int32 = 0; waitpid(pid, &status, 0) }
                free(argv[0])
            }
        }
        spawner.start()
        defer { stop.value = true }
        for _ in 0..<200 {
            let first = try AtlasWorkspaceFiles(directory: scratch.path)
            try first.lock()
            let rival = try AtlasWorkspaceFiles(directory: scratch.path)
            #expect(throws: AtlasRuntimeError("checkpoint_in_use")) { try rival.lock(settle: 0.01) }
            first.unlock()
            let next = try AtlasWorkspaceFiles(directory: scratch.path)
            #expect(throws: Never.self) { try next.lock() }
            next.unlock()
        }
    }
}
